```sql
-- Migration script for ticket C4: add amount_cents derived column

-- 1. Add nullable column
ALTER TABLE orders ADD COLUMN amount_cents bigint;

-- 2. Create trigger function to maintain amount_cents
CREATE OR REPLACE FUNCTION orders_set_amount_cents()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.amount_cents := (NEW.amount * 100)::bigint;
  RETURN NEW;
END;
$$;

-- 3. Attach trigger
CREATE TRIGGER orders_amount_cents_trigger
BEFORE INSERT OR UPDATE ON orders
FOR EACH ROW EXECUTE FUNCTION orders_set_amount_cents();

-- 4. Grant execute to app role
GRANT EXECUTE ON FUNCTION orders_set_amount_cents() TO app;

-- 5. Procedure to backfill existing rows in small batches
CREATE OR REPLACE PROCEDURE backfill_orders_amount_cents()
LANGUAGE plpgsql
AS $$
DECLARE
  batch_size bigint := 10000;
  max_id bigint;
  start_id bigint := 1;
  rows_updated bigint;
BEGIN
  -- Capture max id of rows needing backfill at this point
  SELECT max(id) INTO max_id FROM orders WHERE amount_cents IS NULL;
  IF max_id IS NULL THEN
    RETURN;
  END IF;

  WHILE start_id <= max_id LOOP
    UPDATE orders
    SET amount_cents = (amount * 100)::bigint
    WHERE id >= start_id AND id < start_id + batch_size
    AND amount_cents IS NULL;
    GET DIAGNOSTICS rows_updated = ROW_COUNT;
    COMMIT;
    start_id := start_id + batch_size;
  END LOOP;
END;
$$;

-- 6. Execute backfill
CALL backfill_orders_amount_cents();

-- 7. Add NOT VALID check constraint for NOT NULL
ALTER TABLE orders ADD CONSTRAINT amount_cents_not_null CHECK (amount_cents IS NOT NULL) NOT VALID;

-- 8. Validate constraint (non-blocking for writers)
ALTER TABLE orders VALIDATE CONSTRAINT amount_cents_not_null;

-- 9. Set NOT NULL (fast, uses validated check constraint)
ALTER TABLE orders ALTER COLUMN amount_cents SET NOT NULL;

-- 10. Drop the check constraint (optional)
ALTER TABLE orders DROP CONSTRAINT amount_cents_not_null;

-- 11. Clean up backfill procedure
DROP PROCEDURE backfill_orders_amount_cents();
```

